PREFIX : <https://w3id.org/rastro/proveedores#>
SELECT (SUM(?amt) AS ?total) WHERE {
  { SELECT DISTINCT ?c ?amt WHERE {
      ?c a :Contract ; :agency ?ag ; :amount ?amt ; :supplier ?s .
      ?ag :name ?an . FILTER(STR(?an) = "Department of Defense")
      {
        ?s a :ForeignParentSupplier .
      } UNION {
        ?s :watchlistMatch ?e .
        ?e :entryType ?t . FILTER(STR(?t) = "Entity")
      } UNION {
        ?s :group ?g . ?g :watchlistMatch ?e2 .
        ?e2 :entryType ?t2 . FILTER(STR(?t2) = "Entity")
      }
  } }
}
